    # Initialize output with grid's original special value positions
    output = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Find positions of special value
    positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == special_val]

    # Track positions by column
    by_col = {}
    for (r, c) in positions:
        if c not in by_col:
            by_col[c] = []
        by_col[c].append(r)

    # For each column, shift all positions
    for c in by_col:
        for r in by_col[c]:
            if r - shift >= 0:
                output[r - shift][c] = special_val

    # For consecutive rows in same column, add extra at (first_r - (shift + 1))
    for c in by_col:
        rows = sorted(by_col[c])
        for i in range(len(rows) - 1):
            if rows[i + 1] == rows[i] + 1:  # Consecutive
                if rows[i] - (shift + 1) >= 0:
                    output[rows[i] - (shift + 1)][c] = special_val

    return output

